# Tight stateless IK reduces pressure uncertainty on fine sweeps.
legacy_send=send
def send(P,note=''):
    P=np.asarray(P); seed=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][:7]); acts=[]; lastpose=None
    for pose in P:
        if lastpose is None or np.max(np.abs(lastpose-pose))>1e-7:
            ik=r.ik({'tip':pose},seed=seed,tol_pos_m=.000015,tol_rot_rad=.0001,max_iters=200)
            if not ik['ok']:raise RuntimeError('IK failed '+str(ik))
            seed=np.array(ik['q']);lastpose=pose.copy()
        acts.append(seed.copy())
    with open(OUT+'/commands.jsonl','a') as f:f.write(json.dumps({'type':'joint_position','poses':P.tolist(),'actions':np.array(acts).tolist(),'note':note})+'\n')
    before=r.status()
    try:z=r.submit('joint_position',acts,dt=.05,video='none',cameras=[],note=note)
    except Exception:
        st=r.wait_ready()
        if st['control_steps']==before['control_steps']:z=r.submit('joint_position',acts,dt=.05,video='none',cameras=[],note=note)
        else:raise
    with open(OUT+'/results.jsonl','a') as f:f.write(json.dumps(z.meta)+'\n')
    if z.stopped or z.done:raise RuntimeError(str(z.meta))
    return z

