BasePainter=Painter
class Painter(BasePainter):
    def go(self,p,speed=.18,hold=0):
        return super().go(p,speed,hold)
    def dip(self,c):
        w=WELLS[c].copy();w[2]=.026
        self.go([*self.pos[:2],.050],hold=2)
        self.go([*w[:2],.050]);self.go(w,speed=.065,hold=6)
        self.go([*w[:2],.050],hold=3)
    def sweep_world(self,a,b,depth,speed=.035):
        a=np.array(a);b=np.array(b)
        self.go([*a,.045]);self.go([*a,SURFACE-depth],speed=.065,hold=7)
        self.go([*b,SURFACE-depth],speed=speed,hold=3)
        self.go([*b,.045],speed=.09,hold=4)
